import React, { useState, useEffect, useLayoutEffect, useRef, useCallback } from "react";

const SLIDES = [
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,"
];

const PDF_DATA_URI = "data:application/pdf;base64,";

const PDF_FILENAME = "Oxy-Finserv-DSA-Colending-Bridge-Loans.pdf";

function pad(n) {
  return String(n + 1).padStart(2, "0");
}

export default function OxyFinservLanding() {
  const [current, setCurrent] = useState(0);
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [lbIndex, setLbIndex] = useState(0);
  const [showDeck, setShowDeck] = useState(false);
  const thumbRef = useRef(null);
  const deckRef = useRef(null);

  useLayoutEffect(() => {
    if (window.location.hash) {
      window.history.replaceState(null, "", window.location.pathname + window.location.search);
    }
    window.history.scrollRestoration = "manual";

    const resetScroll = () => {
      window.scrollTo({ top: 0, left: 0, behavior: "auto" });
      document.documentElement.scrollTop = 0;
      document.body.scrollTop = 0;
    };

    resetScroll();

    const frameId = window.requestAnimationFrame(() => {
      resetScroll();
    });
    const timeoutId = window.setTimeout(resetScroll, 0);

    return () => {
      window.cancelAnimationFrame(frameId);
      window.clearTimeout(timeoutId);
    };
  }, []);

  const goTo = useCallback((i) => {
    setCurrent(Math.max(0, Math.min(SLIDES.length - 1, i)));
  }, []);

  useEffect(() => {
    const el = thumbRef.current;
    if (!el) return;
    const active = el.children[current];
    if (active) active.scrollIntoView({ inline: "center", behavior: "smooth", block: "nearest" });
  }, [current]);

  useEffect(() => {
    if (!showDeck) return;
    const frameId = window.requestAnimationFrame(() => {
      if (deckRef.current) {
        deckRef.current.scrollIntoView({ behavior: "smooth" });
      }
    });
    return () => window.cancelAnimationFrame(frameId);
  }, [showDeck]);

  useEffect(() => {
    function onKey(e) {
      if (!lightboxOpen) return;
      if (e.key === "ArrowRight") setLbIndex((i) => Math.min(SLIDES.length - 1, i + 1));
      if (e.key === "ArrowLeft") setLbIndex((i) => Math.max(0, i - 1));
      if (e.key === "Escape") setLightboxOpen(false);
    }
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [lightboxOpen]);

  function openLightbox(i) {
    setLbIndex(i);
    setLightboxOpen(true);
  }

  function downloadPdf(e) {
    e.preventDefault();
    const a = document.createElement("a");
    a.href = PDF_DATA_URI;
    a.download = PDF_FILENAME;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }

  function scrollToDeck() {
    setShowDeck(true);

    const el = deckRef.current || document.getElementById("deck-content");
    if (el) el.scrollIntoView({ behavior: "smooth" });
  }

  return (
    <div className="ofs-root">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,300;9..144,500;9..144,600;9..144,700&family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500&display=swap');

        .ofs-root{
          --navy: #0F1F3D;
          --navy-2: #16264A;
          --green: #1E9254;
          --amber: #E2952F;
          --paper: #F6F3EC;
          --paper-2: #EFEAE0;
          --ink: #1B1B18;
          --ink-soft: #55584f;
          --line: rgba(15,31,61,0.14);
          --max: 1120px;
          background:var(--paper);
          color:var(--ink);
          font-family:'IBM Plex Sans', sans-serif;
          -webkit-font-smoothing:antialiased;
          scrollbar-width:thin;
          scrollbar-color:var(--navy) transparent;
        }
        .ofs-root *{box-sizing:border-box;}
        .ofs-root::-webkit-scrollbar{width:4px;height:4px;}
        .ofs-root::-webkit-scrollbar-track{background:transparent;}
        .ofs-root::-webkit-scrollbar-thumb{background:var(--navy);border-radius:4px;}
        .ofs-root::-webkit-scrollbar-thumb:hover{background:var(--green);}
        .ofs-root img{max-width:100%;display:block;}
        .ofs-root a{color:inherit;}
        .ofs-root h1, .ofs-root h2, .ofs-root h3{
          font-family:'Fraunces', serif; font-weight:600; line-height:1.08; margin:0; letter-spacing:-0.01em;
        }
        .ofs-wrap{max-width:var(--max); margin:0 auto; padding:0 32px;}

        .ofs-nav{
          position:sticky; top:0; z-index:50;
          background:rgba(246,243,236,0.86);
          backdrop-filter:blur(10px);
          border-bottom:1px solid var(--line);
        }
        .ofs-nav-inner{
          max-width:var(--max); margin:0 auto; padding:16px 32px;
          display:flex; align-items:center; justify-content:space-between;
        }
        .ofs-brand{
          display:flex; align-items:baseline; gap:8px;
          font-family:'Fraunces', serif; font-weight:600; font-size:1.15rem;
          color:var(--navy);
        }
        .ofs-brand span{color:var(--green);}
        .ofs-nav-links{display:flex; gap:28px; font-size:0.92rem; color:var(--ink-soft);}
        .ofs-nav-links a{text-decoration:none; transition:color .15s;}
        .ofs-nav-links a:hover{color:var(--navy);}
        .ofs-root .ofs-nav-cta{
          background:var(--navy); color:var(--paper);
          padding:10px 20px; border-radius:3px;
          font-size:0.88rem; font-weight:500; text-decoration:none;
          border:1px solid var(--navy);
          transition:background .15s, color .15s;
        }
        .ofs-nav-cta:hover{background:transparent; color:var(--navy);}

        .ofs-hero{padding:64px 0 88px; position:relative; overflow:hidden;}
        .ofs-hero-grid{display:grid; grid-template-columns:1fr; gap:48px; align-items:center;}
        .ofs-eyebrow{
          display:flex; align-items:center; gap:10px;
          font-family:'IBM Plex Mono', monospace;
          font-size:0.72rem; color:var(--green); margin-bottom:18px;
          text-transform:uppercase; letter-spacing:0.06em;
        }
        .ofs-eyebrow .dot{width:6px;height:6px;border-radius:50%;background:var(--green);}
        .ofs-hero h1{font-size:clamp(2.4rem, 5vw, 3.6rem); color:var(--navy); max-width:14ch;}
        .ofs-hero p.lede{margin-top:20px; font-size:1.12rem; line-height:1.55; color:var(--ink-soft); max-width:52ch;}
        .ofs-hero-ctas{display:flex; gap:14px; margin-top:32px; flex-wrap:wrap;}

        .ofs-btn{
          display:inline-flex; align-items:center; gap:8px;
          padding:14px 26px; border-radius:3px;
          font-size:0.95rem; font-weight:500; text-decoration:none;
          cursor:pointer; border:1px solid transparent;
          transition:transform .15s ease, box-shadow .15s ease;
        }
        .ofs-btn:active{transform:translateY(1px);}
        .ofs-btn-primary{background:var(--green); color:#fff;}
        .ofs-btn-primary:hover{box-shadow:0 6px 20px rgba(30,146,84,0.35);}
        .ofs-btn-outline{background:transparent; color:var(--navy); border-color:var(--navy);}
        .ofs-btn-outline:hover{background:var(--navy); color:var(--paper);}

        .ofs-screen-mock{position:relative; max-width:520px; margin:0;}
        .ofs-screen-bezel{
          background:var(--navy); border-radius:14px 14px 4px 4px;
          padding:14px 14px 40px; box-shadow:0 30px 60px -20px rgba(15,31,61,0.45);
        }
        .ofs-screen-dots{display:flex; gap:6px; padding:0 4px 12px;}
        .ofs-screen-dots span{width:9px;height:9px;border-radius:50%;background:rgba(255,255,255,0.25);}
        .ofs-screen-inner{border-radius:4px; overflow:hidden; background:#fff; cursor:pointer; position:relative;}
        .ofs-screen-inner img{width:100%; display:block;}
        .ofs-play-hint{
          position:absolute; inset:0; display:flex; align-items:center; justify-content:center;
          background:rgba(15,31,61,0); transition:background .2s;
        }
        .ofs-screen-inner:hover .ofs-play-hint{background:rgba(15,31,61,0.28);}
        .ofs-play-hint span{
          opacity:0; transform:scale(0.9); transition:opacity .2s, transform .2s;
          background:#fff; color:var(--navy); padding:12px 22px; border-radius:30px;
          font-size:0.85rem; font-weight:600; display:flex; align-items:center; gap:8px;
        }
        .ofs-screen-inner:hover .ofs-play-hint span{opacity:1; transform:scale(1);}
        .ofs-screen-stand{width:140px; height:16px; margin:0 auto; background:linear-gradient(180deg, var(--navy-2), var(--navy)); border-radius:0 0 10px 10px;}
        .ofs-screen-base{width:220px; height:8px; margin:0 auto; background:var(--navy-2); border-radius:6px; opacity:0.6;}

        .ofs-stats{background:var(--navy); color:var(--paper); padding:46px 0;}
        .ofs-stats-row{display:grid; grid-template-columns:repeat(4,1fr); gap:24px;}
        .ofs-stat b{display:block; font-family:'Fraunces', serif; font-weight:600; font-size:2.1rem; color:#fff;}
        .ofs-stat span{display:block; margin-top:6px; font-size:0.85rem; color:rgba(246,243,236,0.65);}

        .ofs-section{padding:88px 0;}
        .ofs-section-head{max-width:640px; margin-bottom:48px;}
        .ofs-kicker{
          font-family:'IBM Plex Mono', monospace; font-size:0.72rem;
          color:var(--amber); text-transform:uppercase; letter-spacing:0.06em;
          margin-bottom:14px; display:block;
        }
        .ofs-section-head h2{font-size:clamp(1.7rem,3vw,2.3rem); color:var(--navy);}
        .ofs-section-head p{margin-top:14px; color:var(--ink-soft); line-height:1.6; font-size:1.02rem;}

        .ofs-viewer{background:var(--paper-2); border:1px solid var(--line); border-radius:6px; padding:28px;}
        .ofs-viewer-stage{
          position:relative; background:#fff; border-radius:4px;
          box-shadow:0 20px 45px -25px rgba(15,31,61,0.4); overflow:hidden;
        }
        .ofs-viewer-stage img{width:100%; display:block; cursor:pointer;}
        .ofs-viewer-controls{display:flex; align-items:center; justify-content:space-between; margin-top:20px;}
        .ofs-vc-btn{
          background:var(--navy); color:#fff; border:none; width:42px; height:42px; border-radius:50%;
          font-size:1.1rem; cursor:pointer; display:flex; align-items:center; justify-content:center;
          transition:background .15s;
        }
        .ofs-vc-btn:hover{background:var(--green);}
        .ofs-vc-btn:disabled{opacity:0.3; cursor:not-allowed;}
        .ofs-vc-count{font-family:'IBM Plex Mono', monospace; font-size:0.85rem; color:var(--ink-soft);}
        .ofs-thumbs{display:flex; gap:10px; margin-top:22px; overflow-x:auto; padding-bottom:6px;}
        .ofs-thumbs{scrollbar-width:thin; scrollbar-color:var(--navy) transparent;}
        .ofs-thumbs::-webkit-scrollbar{height:4px;}
        .ofs-thumbs::-webkit-scrollbar-track{background:transparent;}
        .ofs-thumbs::-webkit-scrollbar-thumb{background:var(--navy); border-radius:4px;}
        .ofs-thumb{
          flex:0 0 auto; width:96px; border-radius:3px; overflow:hidden;
          cursor:pointer; border:2px solid transparent; opacity:0.55;
          transition:opacity .15s, border-color .15s;
        }
        .ofs-thumb img{width:100%; display:block;}
        .ofs-thumb.active{opacity:1; border-color:var(--green);}
        .ofs-thumb:hover{opacity:1;}

        .ofs-models-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:24px;}
        .ofs-model-card{background:#fff; border:1px solid var(--line); border-radius:6px; padding:32px 26px;}
        .ofs-model-card .num{font-family:'IBM Plex Mono', monospace; font-size:0.78rem; color:var(--green); margin-bottom:16px; display:block;}
        .ofs-model-card h3{font-size:1.25rem; color:var(--navy); margin-bottom:12px;}
        .ofs-model-card p{color:var(--ink-soft); line-height:1.55; font-size:0.96rem; margin:0 0 16px;}
        .ofs-model-card ul{margin:0; padding-left:18px; color:var(--ink-soft); font-size:0.92rem; line-height:1.7;}

        .ofs-bureaus{display:flex; flex-wrap:wrap; gap:16px; margin-top:8px;}
        .ofs-bureau-pill{
          display:flex; align-items:center; gap:10px; background:#fff; border:1px solid var(--line);
          border-radius:30px; padding:10px 18px; font-size:0.9rem; color:var(--navy); font-weight:500;
        }
        .ofs-bureau-pill .check{color:var(--green); font-weight:700;}

        .ofs-cta-band{
          background:var(--green); color:#fff; border-radius:8px; padding:56px 48px;
          display:flex; align-items:center; justify-content:space-between; gap:32px; flex-wrap:wrap;
        }
        .ofs-cta-band h2{color:#fff; font-size:1.9rem; max-width:16ch;}
        .ofs-cta-band p{color:rgba(255,255,255,0.85); margin-top:10px; max-width:40ch; line-height:1.5;}
        .ofs-cta-band .ofs-btn-primary{background:#fff; color:var(--green);}
        .ofs-cta-band .ofs-btn-primary:hover{box-shadow:0 6px 20px rgba(0,0,0,0.2);}

        .ofs-footer{border-top:1px solid var(--line); padding:36px 0; margin-top:20px;}
        .ofs-foot-row{
          display:flex; justify-content:space-between; align-items:center;
          font-size:0.85rem; color:var(--ink-soft); flex-wrap:wrap; gap:12px;
        }

        .ofs-lightbox{
          position:fixed; inset:0; background:rgba(15,31,61,0.92);
          display:none; align-items:center; justify-content:center; z-index:200; padding:40px; flex-direction:column;
        }
        .ofs-lightbox.open{display:flex;}
        .ofs-lightbox-stage{max-width:900px; width:100%; position:relative;}
        .ofs-lightbox-stage img{width:100%; border-radius:4px; box-shadow:0 30px 70px rgba(0,0,0,0.5);}
        .ofs-lb-close{position:absolute; top:-46px; right:0; background:none; border:none; color:#fff; font-size:1.6rem; cursor:pointer; line-height:1;}
        .ofs-lb-nav{display:flex; justify-content:space-between; width:100%; max-width:900px; margin-top:18px;}
        .ofs-lb-nav button{
          background:rgba(255,255,255,0.12); border:1px solid rgba(255,255,255,0.25);
          color:#fff; width:44px; height:44px; border-radius:50%; font-size:1.1rem; cursor:pointer;
        }
        .ofs-lb-count{color:rgba(255,255,255,0.7); font-size:0.85rem; font-family:'IBM Plex Mono', monospace; align-self:center;}

        .ofs-contact-grid{display:grid; grid-template-columns:repeat(2,1fr); gap:20px;}
        .ofs-contact-card{
          background:#fff; border:1px solid var(--line); border-radius:6px;
          padding:26px 24px; display:flex; gap:16px; align-items:flex-start;
        }
        .ofs-contact-avatar{
          width:52px; height:52px; border-radius:50%; flex:0 0 auto;
          background:var(--navy); color:#fff; display:flex; align-items:center; justify-content:center;
          font-family:'Fraunces', serif; font-weight:600; font-size:1.1rem;
        }
        .ofs-contact-card h3{font-size:1.05rem; color:var(--navy); margin-bottom:2px;}
        .ofs-contact-role{font-size:0.85rem; color:var(--green); font-weight:500; margin-bottom:10px;}
        .ofs-contact-meta{display:flex; flex-direction:column; gap:6px; font-size:0.88rem; color:var(--ink-soft);}
        .ofs-contact-meta a{text-decoration:none; color:var(--ink-soft); transition:color .15s;}
        .ofs-contact-meta a:hover{color:var(--navy); text-decoration:underline;}
        .ofs-contact-meta .icon{margin-right:6px;}

        @media (min-width:860px){
          .ofs-hero-grid{grid-template-columns:1.05fr 0.95fr;}
          .ofs-hero-ctas{flex-wrap:nowrap;}
        }
        @media (max-width:860px){
          .ofs-stats-row{grid-template-columns:repeat(2,1fr); row-gap:28px;}
          .ofs-models-grid{grid-template-columns:1fr;}
          .ofs-nav-links{display:none;}
          .ofs-cta-band{flex-direction:column; align-items:flex-start;}
          .ofs-contact-grid{grid-template-columns:1fr;}
        }
      `}</style>

      <nav className="ofs-nav">
        <div className="ofs-nav-inner">
          <div className="ofs-brand">OXY<span>FINSERV</span></div>
          <div className="ofs-nav-links">
            <a href="#deck-content" onClick={(e) => { e.preventDefault(); scrollToDeck(); }}>The Deck</a>
            <a href="#models">Partnership Models</a>
            <a href="#trust">Trust &amp; Data</a>
            <a href="#team">Team</a>
          </div>
          <a className="ofs-nav-cta" href="#download">Download PDF</a>
        </div>
      </nav>

    <section id="header">
      <header className="ofs-hero">
        <div className="ofs-wrap ofs-hero-grid">
          <div>
            <div className="ofs-eyebrow"><span className="dot"></span>AN OXYLOANS INITIATIVE · DSA · CO-LENDING · BRIDGE LOANS</div>
            <h1>Lending that moves at the speed of Bharat.</h1>
            <p className="lede">Oxy Finserv connects regulated banks and NBFCs with everyday borrowers across India — through compliant sourcing, escrow-backed disbursal, and a decade of on-ground lending experience.</p>
            <div className="ofs-hero-ctas">
              <a className="ofs-btn ofs-btn-primary" href="#deck-content" onClick={(e) => { e.preventDefault(); scrollToDeck(); }}>View the presentation</a>
              <a className="ofs-btn ofs-btn-outline" href="#" onClick={downloadPdf}>Download PDF ↓</a>
            </div>
          </div>

          <div className="ofs-screen-mock">
            <div className="ofs-screen-bezel">
              <div className="ofs-screen-dots"><span></span><span></span><span></span></div>
              <div className="ofs-screen-inner" onClick={scrollToDeck}>
                <img src={SLIDES[0]} alt="Opening slide of the Oxy Finserv deck" />
                <div className="ofs-play-hint"><span>▸ Open full deck</span></div>
              </div>
            </div>
            <div className="ofs-screen-stand"></div>
            <div className="ofs-screen-base"></div>
          </div>
        </div>
      </header>
    </section>

      <section className="ofs-stats">
        <div className="ofs-wrap ofs-stats-row">
          <div className="ofs-stat"><b>10</b><span>Years lending, trusted since 2016</span></div>
          <div className="ofs-stat"><b>4,800+</b><span>Active lenders on the platform</span></div>
          <div className="ofs-stat"><b>₹1,700 Cr+</b><span>Cumulative transactions</span></div>
          <div className="ofs-stat"><b>70+</b><span>Employees across offices</span></div>
        </div>
      </section>

      {showDeck && (
        <section className="ofs-section" id="deck-content" ref={deckRef}>
          <div className="ofs-wrap">
            <div className="ofs-section-head">
              <span className="ofs-kicker">13 slides</span>
              <h2>Walk through the full deck</h2>
              <p>Every slide from the partnership presentation, browsable right here — from how OXY works end to end, to the DSA, bridge loan, and co-lending models on offer.</p>
            </div>

            <div className="ofs-viewer">
              <div className="ofs-viewer-stage">
                <img src={SLIDES[current]} alt={`Slide ${current + 1}`} onClick={() => openLightbox(current)} />
              </div>
              <div className="ofs-viewer-controls">
                <button className="ofs-vc-btn" onClick={() => goTo(current - 1)} disabled={current === 0} aria-label="Previous slide">‹</button>
                <span className="ofs-vc-count">{pad(current)} / {SLIDES.length}</span>
                <button className="ofs-vc-btn" onClick={() => goTo(current + 1)} disabled={current === SLIDES.length - 1} aria-label="Next slide">›</button>
              </div>
              <div className="ofs-thumbs" ref={thumbRef}>
                {SLIDES.map((src, i) => (
                  <div
                    key={i}
                    className={"ofs-thumb" + (i === current ? " active" : "")}
                    onClick={() => goTo(i)}
                  >
                    <img src={src} alt={`Slide ${i + 1} thumbnail`} />
                  </div>
                ))}
              </div>
            </div>
          </div>
        </section>
      )}

      <section className="ofs-section" id="models">
        <div className="ofs-wrap">
          <div className="ofs-section-head">
            <span className="ofs-kicker">Three ways to partner</span>
            <h2>Built to plug into your lending book</h2>
            <p>Oxy Finserv sources, verifies, and services borrowers — you decide how deep the partnership goes.</p>
          </div>
          <div className="ofs-models-grid">
            <div className="ofs-model-card">
              <span className="num">01 — DSA</span>
              <h3>Direct Selling Agent</h3>
              <p>We source, KYC-verify, and document borrowers on your behalf. The loan books directly with you as the bank or NBFC partner.</p>
              <ul>
                <li>Wider, digitally-sourced borrower reach</li>
                <li>We absorb sourcing costs, lowering CAC</li>
                <li>Dedicated servicing through the loan lifecycle</li>
              </ul>
            </div>
            <div className="ofs-model-card">
              <span className="num">02 — BRIDGE LOAN</span>
              <h3>Bridge Loan Partnership</h3>
              <p>We onboard, clear the borrower's smaller existing loans, and season the consolidated loan for 1–2 months before handing it over, clean.</p>
              <ul>
                <li>Open to banks, NBFCs, family houses, alternative funds</li>
                <li>Bridge capital is released back for reuse after handover</li>
                <li>Acquire → Clean up → Season → Hand over → Release</li>
              </ul>
            </div>
            <div className="ofs-model-card">
              <span className="num">03 — CO-LENDING</span>
              <h3>Co-Lending Partnership</h3>
              <p>We jointly fund eligible borrowers alongside NBFC and bank partners, sharing risk across personal loans and gold loans.</p>
              <ul>
                <li>Priority 1: Personal loans for core co-lending volume</li>
                <li>Priority 2: Gold loans, asset-backed and fast</li>
                <li>Shared risk, stronger portfolio quality</li>
              </ul>
            </div>
          </div>
        </div>
      </section>

      <section className="ofs-section" id="trust">
        <div className="ofs-wrap">
          <div className="ofs-section-head">
            <span className="ofs-kicker">Underwriting</span>
            <h2>Every borrower checked against four bureaus</h2>
            <p>Live, multi-source bureau pulls feed directly into the credit engine — for faster decisions and stronger portfolio quality.</p>
          </div>
          <div className="ofs-bureaus">
            <div className="ofs-bureau-pill"><span className="check">✓</span> Experian</div>
            <div className="ofs-bureau-pill"><span className="check">✓</span> Equifax</div>
            <div className="ofs-bureau-pill"><span className="check">✓</span> CRIF High Mark</div>
            <div className="ofs-bureau-pill"><span className="check">✓</span> TransUnion</div>
          </div>
        </div>
      </section>

      <section className="ofs-section" id="download">
        <div className="ofs-wrap">
          <div className="ofs-cta-band">
            <div>
              <h2>Take the deck with you</h2>
              <p>Get the full Oxy Finserv presentation as a PDF — every slide, model, and stat, ready to share with your team.</p>
            </div>
            <a className="ofs-btn ofs-btn-primary" href="#" onClick={downloadPdf}>Download PDF ↓</a>
          </div>
        </div>
      </section>

      {/* <section className="ofs-section" id="team" style={{ paddingBottom: 0 }}>
        <div className="ofs-wrap">
          <div className="ofs-section-head">
            <span className="ofs-kicker">Leadership</span>
            <h2>An OxyLoans initiative</h2>
            <p>Part of the OxyGlobal.Tech ecosystem — spanning OxyLoans, AskOxy.AI, OxyGold, OxyBricks, and OxyChain.</p>
          </div>
        </div>
      </section> */}

      <section className="ofs-section" id="contact">
        <div className="ofs-wrap">
          <div className="ofs-section-head">
            <span className="ofs-kicker">Point of Contact</span>
            <h2>Let's talk partnership</h2>
            <p>Reach out to get a DSA, co-lending, or bridge loan partnership moving — direct lines to the team below.</p>
          </div>

          <div className="ofs-contact-grid">
            <div className="ofs-contact-card">
              <div className="ofs-contact-avatar">P</div>
              <div>
                <h3>Prameela Kovvali</h3>
                {/* <div className="ofs-contact-role">Manager, Oxy Finserv · Hyderabad</div> */}
                <div className="ofs-contact-meta">
                  <a href="mailto:team@oxyloans.in"><span className="icon">✉</span>team@oxyloans.in</a>
                  <a href="tel:+91-9493967848"><span className="icon">☎</span>+91 949 396 7848</a>
                  {/* <a href="https://www.linkedin.com/in/oxyradhakrishna" target="_blank" rel="noopener noreferrer"><span className="icon">in</span>linkedin.com/in/oxyradhakrishna</a> */}
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      <footer className="ofs-footer">
        <div className="ofs-wrap ofs-foot-row">
          <span>OXY FINSERV — DSA Partner · Co-Lending Partner · Bridge Loan Partner</span>
          <span>Open for partnerships</span>
        </div>
      </footer>

      <div className={"ofs-lightbox" + (lightboxOpen ? " open" : "")} onClick={(e) => { if (e.target === e.currentTarget) setLightboxOpen(false); }}>
        <div className="ofs-lightbox-stage">
          <button className="ofs-lb-close" onClick={() => setLightboxOpen(false)}>&times;</button>
          <img src={SLIDES[lbIndex]} alt={`Slide ${lbIndex + 1}`} />
        </div>
        <div className="ofs-lb-nav">
          <button onClick={() => setLbIndex((i) => Math.max(0, i - 1))}>‹</button>
          <span className="ofs-lb-count">{pad(lbIndex)} / {SLIDES.length}</span>
          <button onClick={() => setLbIndex((i) => Math.min(SLIDES.length - 1, i + 1))}>›</button>
        </div>
      </div>
    </div>
  );
}
